'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "width": 479.0,
  "height": 146,
  "transform": [
    {
      "calculate": "toNumber(slice(datum[''Month''], -4)) * 12 + indexof([''Jan'',''Feb'',''Mar'',''Apr'',''May'',''Jun'',''Jul'',''Aug'',''Sep'',''Oct'',''Nov'',''Dec''], slice(datum[''Month''], 0, 3))",
      "as": "mi"
    },
    {
      "calculate": "indexof([''Semi-urban'', ''Urban''], datum[''Patient Area''])",
      "as": "ord"
    },
    {
      "stack": "Missed Visit Fees",
      "groupby": [
        "Month"
      ],
      "sort": [
        {
          "field": "ord"
        }
      ],
      "as": [
        "y0",
        "y1"
      ]
    },
    {
      "joinaggregate": [
        {
          "op": "sum",
          "field": "Missed Visit Fees",
          "as": "month_total"
        }
      ],
      "groupby": [
        "Month"
      ]
    },
    {
      "joinaggregate": [
        {
          "op": "sum",
          "field": "Missed Visit Fees",
          "as": "grand"
        },
        {
          "op": "max",
          "field": "month_total",
          "as": "peak"
        }
      ]
    },
    {
      "calculate": "slice(datum[''Month''], 0, 3)",
      "as": "mon"
    }
  ],
  "layer": [
    {
      "transform": [
        {
          "filter": "datum[''Patient Area''] == ''Semi-urban''"
        }
      ],
      "mark": {
        "type": "bar",
        "stroke": "white",
        "strokeWidth": 1.5,
        "color": {
          "x1": 0,
          "y1": 1,
          "x2": 0,
          "y2": 0,
          "gradient": "linear",
          "stops": [
            {
              "offset": 0,
              "color": "#F59B6B"
            },
            {
              "offset": 1,
              "color": "#EB6834"
            }
          ]
        }
      },
      "encoding": {
        "x": {
          "field": "mon",
          "type": "ordinal",
          "sort": {
            "field": "mi"
          },
          "title": null,
          "scale": {
            "paddingInner": 0.34,
            "paddingOuter": 0.2
          },
          "axis": {
            "labelAngle": 0,
            "labelColor": "#667085",
            "labelFontSize": 10,
            "domain": false,
            "ticks": false,
            "labelPadding": 6
          }
        },
        "y": {
          "type": "quantitative",
          "title": null,
          "axis": null,
          "scale": {
            "domainMax": 1050000,
            "nice": false
          },
          "field": "y0"
        },
        "y2": {
          "field": "y1"
        },
        "tooltip": [
          {
            "field": "Month"
          },
          {
            "field": "Patient Area"
          },
          {
            "field": "Missed Visit Fees",
            "format": ",.0f",
            "title": "Fees (BDT)"
          }
        ]
      }
    },
    {
      "transform": [
        {
          "filter": "datum[''Patient Area''] == ''Urban''"
        }
      ],
      "mark": {
        "type": "bar",
        "stroke": "white",
        "strokeWidth": 1.5,
        "cornerRadiusTopLeft": 5,
        "cornerRadiusTopRight": 5,
        "color": {
          "x1": 0,
          "y1": 1,
          "x2": 0,
          "y2": 0,
          "gradient": "linear",
          "stops": [
            {
              "offset": 0,
              "color": "#6AA6EA"
            },
            {
              "offset": 1,
              "color": "#2A78D6"
            }
          ]
        }
      },
      "encoding": {
        "x": {
          "field": "mon",
          "type": "ordinal",
          "sort": {
            "field": "mi"
          },
          "title": null,
          "scale": {
            "paddingInner": 0.34,
            "paddingOuter": 0.2
          },
          "axis": {
            "labelAngle": 0,
            "labelColor": "#667085",
            "labelFontSize": 10,
            "domain": false,
            "ticks": false,
            "labelPadding": 6
          }
        },
        "y": {
          "type": "quantitative",
          "title": null,
          "axis": null,
          "scale": {
            "domainMax": 1050000,
            "nice": false
          },
          "field": "y0"
        },
        "y2": {
          "field": "y1"
        },
        "tooltip": [
          {
            "field": "Month"
          },
          {
            "field": "Patient Area"
          },
          {
            "field": "Missed Visit Fees",
            "format": ",.0f",
            "title": "Fees (BDT)"
          }
        ]
      }
    },
    {
      "transform": [
        {
          "filter": "datum[''Patient Area''] == ''Urban''"
        },
        {
          "calculate": "format(datum.month_total / 1e3, ''.0f'') + ''k''",
          "as": "lab"
        }
      ],
      "mark": {
        "type": "text",
        "dy": -7,
        "fontSize": 10,
        "fontWeight": 600,
        "color": "#344054"
      },
      "encoding": {
        "x": {
          "field": "mon",
          "type": "ordinal",
          "sort": {
            "field": "mi"
          },
          "title": null,
          "scale": {
            "paddingInner": 0.34,
            "paddingOuter": 0.2
          },
          "axis": {
            "labelAngle": 0,
            "labelColor": "#667085",
            "labelFontSize": 10,
            "domain": false,
            "ticks": false,
            "labelPadding": 6
          }
        },
        "y": {
          "type": "quantitative",
          "title": null,
          "axis": null,
          "scale": {
            "domainMax": 1050000,
            "nice": false
          },
          "field": "y1"
        },
        "text": {
          "field": "lab"
        }
      }
    },
    {
      "transform": [
        {
          "aggregate": [
            {
              "op": "max",
              "field": "grand",
              "as": "grand"
            }
          ]
        },
        {
          "calculate": "''\u2248 '' + ((datum.grand) >= 1e6 ? ''BDT '' + format((datum.grand) / 1e6, ''.1f'') + ''M'' : ''BDT '' + format((datum.grand) / 1e3, ''.0f'') + ''k'')",
          "as": "t"
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "top",
        "fontSize": 21,
        "fontWeight": 700,
        "color": "#101828"
      },
      "encoding": {
        "x": {
          "value": 2
        },
        "y": {
          "value": 0
        },
        "text": {
          "field": "t"
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum[''Patient Area''] == ''Semi-urban''"
        },
        {
          "aggregate": [
            {
              "op": "sum",
              "field": "Missed Visit Fees",
              "as": "su"
            },
            {
              "op": "max",
              "field": "grand",
              "as": "grand"
            }
          ]
        },
        {
          "calculate": "''not collected \u00b7 '' + format(datum.su / datum.grand, ''.0%'') + '' from semi-urban patients''",
          "as": "t"
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "top",
        "fontSize": 10.5,
        "color": "#667085"
      },
      "encoding": {
        "x": {
          "value": 2
        },
        "y": {
          "value": 28
        },
        "text": {
          "field": "t"
        }
      }
    },
    {
      "transform": [
        {
          "aggregate": [
            {
              "op": "count",
              "as": "n"
            }
          ]
        }
      ],
      "mark": {
        "type": "rect",
        "cornerRadius": 2,
        "color": "#EB6834"
      },
      "encoding": {
        "x": {
          "value": 329.0
        },
        "x2": {
          "value": 338.0
        },
        "y": {
          "value": 4
        },
        "y2": {
          "value": 13
        }
      }
    },
    {
      "transform": [
        {
          "aggregate": [
            {
              "op": "count",
              "as": "n"
            }
          ]
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "middle",
        "fontSize": 10.5,
        "color": "#344054"
      },
      "encoding": {
        "x": {
          "value": 343.0
        },
        "y": {
          "value": 9
        },
        "text": {
          "value": "Semi-urban"
        }
      }
    },
    {
      "transform": [
        {
          "aggregate": [
            {
              "op": "count",
              "as": "n"
            }
          ]
        }
      ],
      "mark": {
        "type": "rect",
        "cornerRadius": 2,
        "color": "#2A78D6"
      },
      "encoding": {
        "x": {
          "value": 415.0
        },
        "x2": {
          "value": 424.0
        },
        "y": {
          "value": 4
        },
        "y2": {
          "value": 13
        }
      }
    },
    {
      "transform": [
        {
          "aggregate": [
            {
              "op": "count",
              "as": "n"
            }
          ]
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "middle",
        "fontSize": 10.5,
        "color": "#344054"
      },
      "encoding": {
        "x": {
          "value": 429.0
        },
        "y": {
          "value": 9
        },
        "text": {
          "value": "Urban"
        }
      }
    }
  ],
  "autosize": {
    "type": "pad"
  },
  "padding": {
    "left": 2,
    "right": 2,
    "top": 2,
    "bottom": 0
  }
}'

